#pragma once
#include "NotePresets.h"
static void testNotePresets(const File& root){
    auto file=root.getChildFile("note-presets-checks.json");file.deleteFile();std::vector<NotePreset> rows;
    expect(loadNotePresets(file,rows).wasOk()&&rows.empty(),"missing preset library starts empty");
    bool factoriesValid=true,roundtrip=true;for(int mode=0;mode<4;++mode)for(auto p:factoryNotePresets((NoteToolMode)mode)){factoriesValid&=validateNotePreset(p).wasOk();NotePreset read;roundtrip&=notePresetFromJson(notePresetToJson(p),read).wasOk()&&JSON::toString(notePresetToJson(p))==JSON::toString(notePresetToJson(read));}
    expect(factoriesValid,"all twelve factory note presets have valid settings");expect(roundtrip,"all four note preset modes serialize and decode exactly");
    NotePreset p;p.id="personal-one";p.name=String::fromUTF8("Мой ритм");p.mode=NoteToolMode::humanize;p.notes.mode=p.mode;p.notes.seed=4294967295u;p.notes.timing=.043;p.notes.length=.037;p.notes.velocity=.18;p.notes.keepChords=false;
    expect(putNotePreset(file,p).wasOk(),"save a Unicode-named personal humanize preset");expect(loadNotePresets(file,rows).wasOk()&&rows.size()==1&&rows[0].name==p.name&&rows[0].notes.seed==4294967295u,"preset reload retains Unicode names and full unsigned seeds");
    std::vector<Note> source={{.13,.37,60,.8f},{.13,.37,64,.6f},{2,.5,67,.9f}},a,b;processNotes(source,8,{},p.notes,a);processNotes(source,8,{},rows[0].notes,b);expect(a==b&&a!=source,"reloaded humanize preset reproduces deterministic note output");
    auto saved=file.loadFileAsString();expect(putNotePreset(file,p).failed()&&file.loadFileAsString()==saved,"new preset cannot replace an existing identity implicitly");auto duplicate=p;duplicate.id="personal-two";expect(putNotePreset(file,duplicate).failed()&&file.loadFileAsString()==saved,"same-tool duplicate names cannot overwrite presets");
    duplicate.mode=NoteToolMode::arpeggiator;duplicate.arp.order=ArpOrder::random;duplicate.arp.seed=4294967295u;expect(putNotePreset(file,duplicate).wasOk(),"different tools may use the same preset name");
    p.name="Renamed performance";p.notes.seed=7;expect(putNotePreset(file,p,true).wasOk()&&loadNotePresets(file,rows).wasOk()&&rows.size()==2&&rows[0].name==p.name&&rows[0].notes.seed==7,"explicit update renames one identity and persists revised settings");
    auto stale=p;stale.id="missing-id";saved=file.loadFileAsString();expect(putNotePreset(file,stale,true).failed()&&file.loadFileAsString()==saved,"updating a removed preset never recreates it silently");stale=p;stale.mode=NoteToolMode::quantize;expect(putNotePreset(file,stale,true).failed()&&file.loadFileAsString()==saved,"updating cannot change the tool of an existing preset");
    auto exportFile=root.getChildFile("single-note-preset.json");expect(saveNotePresets(exportFile,{duplicate}).wasOk()&&loadNotePresets(exportFile,rows).wasOk()&&rows.size()==1&&rows[0].arp.seed==4294967295u,"single-preset export and relocated import retain all arpeggiator settings");
    arpeggiateNotes(source,8,{},duplicate.arp,a);arpeggiateNotes(source,8,{},rows[0].arp,b);expect(a==b,"exported random arpeggiator reproduces identical pitches and gates");
    auto triplet=duplicate;triplet.arp.rate=1./6;saveNotePresets(exportFile,{triplet});loadNotePresets(exportFile,rows);arpeggiateNotes(source,8,{},triplet.arp,a);arpeggiateNotes(source,8,{},rows[0].arp,b);expect(rows[0].arp.rate==triplet.arp.rate&&a==b,"triplet preset disk roundtrip preserves exact timing and generated notes");
    auto json=notePresetToJson(duplicate);auto text=JSON::toString(json);expect(!json.hasProperty("path")&&!json.hasProperty("lanes")&&!json["settings"].hasProperty("pitch")&&!json["settings"].hasProperty("start")&&!json["settings"].hasProperty("end"),"preset exports exclude project notes, paths and target ranges");
    auto invalid=root.getChildFile("invalid-note-presets.json");invalid.replaceWithText("{broken");rows={p};expect(loadNotePresets(invalid,rows).failed()&&rows.size()==1&&rows[0].id==p.id,"invalid JSON leaves caller preset library unchanged");expect(putNotePreset(invalid,p).failed()&&invalid.loadFileAsString()=="{broken","saving refuses to replace a corrupt preset library");
    auto bad=notePresetToJson(duplicate);bad["settings"].getDynamicObject()->setProperty("seed",4294967296LL);NotePreset output=p;expect(notePresetFromJson(bad,output).failed()&&output.id==p.id,"overflowed preset seed is rejected atomically");
    bad=notePresetToJson(duplicate);bad["settings"].getDynamicObject()->setProperty("restart",1);expect(notePresetFromJson(bad,output).failed(),"numeric values cannot masquerade as preset booleans");
    bad=notePresetToJson(duplicate);bad["settings"].getDynamicObject()->setProperty("octaves",1.5);expect(notePresetFromJson(bad,output).failed(),"fractional octave values cannot be truncated into valid presets");
    bad=notePresetToJson(duplicate);bad["settings"].getDynamicObject()->removeProperty("gate");expect(notePresetFromJson(bad,output).failed(),"incomplete preset settings are rejected rather than defaulted");
    bad=notePresetToJson(duplicate);bad.getDynamicObject()->setProperty("mode","future-tool");expect(notePresetFromJson(bad,output).failed(),"unknown preset tool is rejected");
    auto invalidPreset=p;invalidPreset.notes.timing=std::numeric_limits<double>::infinity();saved=file.loadFileAsString();expect(putNotePreset(file,invalidPreset,true).failed()&&file.loadFileAsString()==saved,"nonfinite settings do not damage existing preset files");
    invalidPreset=p;invalidPreset.name=" bad name ";expect(validateNotePreset(invalidPreset).failed(),"preset names reject leading or trailing whitespace");invalidPreset.name="bad\nname";expect(validateNotePreset(invalidPreset).failed(),"preset names reject embedded control characters");invalidPreset=p;invalidPreset.id="../outside";expect(validateNotePreset(invalidPreset).failed(),"preset identities cannot contain paths");
    auto q=factoryNotePresets(NoteToolMode::quantize)[0];q.id="case-name";q.name="RENAMED PERFORMANCE";q.mode=NoteToolMode::humanize;expect(putNotePreset(file,q).failed(),"same-tool name uniqueness ignores case");
    auto schema=JSON::parse(file.loadFileAsString());schema.getDynamicObject()->setProperty("schema",2);invalid.replaceWithText(JSON::toString(schema));expect(loadNotePresets(invalid,rows).failed(),"future preset library schema is rejected");schema.getDynamicObject()->setProperty("schema",1);schema["presets"].getArray()->add(schema["presets"][0]);invalid.replaceWithText(JSON::toString(schema));expect(loadNotePresets(invalid,rows).failed(),"duplicate IDs in imported files fail as a complete library");
    invalid.replaceWithText(String::repeatedString(" ",262145));expect(loadNotePresets(invalid,rows).failed(),"oversized preset files fail before JSON parsing");
    std::vector<NotePreset> full;for(int i=0;i<maxNotePresets;++i){auto row=p;row.id="preset-"+String(i);row.name="Performance "+String(i);full.push_back(row);}auto limitFile=root.getChildFile("full-note-presets.json");expect(saveNotePresets(limitFile,full).wasOk(),"preset library accepts exactly 128 entries");saved=limitFile.loadFileAsString();expect(putNotePreset(limitFile,p).failed()&&limitFile.loadFileAsString()==saved,"preset capacity failure leaves the full library intact");
    auto blocker=root.getChildFile("preset-save-blocker");blocker.replaceWithText("KEEP");expect(saveNotePresets(blocker.getChildFile("presets.json"),{p}).failed()&&blocker.loadFileAsString()=="KEEP","unwritable parent fails without replacing existing files");
    expect(removeNotePreset(file,p.id).wasOk()&&loadNotePresets(file,rows).wasOk()&&rows.size()==1&&rows[0].id==duplicate.id,"preset deletion removes only the requested identity");saved=file.loadFileAsString();expect(removeNotePreset(file,p.id).failed()&&file.loadFileAsString()==saved,"stale preset deletion preserves other entries");
    auto rhythm=factoryNotePresets(NoteToolMode::euclidean)[0];rhythm.rhythm.pitch=127;rhythm.rhythm.start=5;rhythm.rhythm.end=6;NotePreset decoded;expect(notePresetFromJson(notePresetToJson(rhythm),decoded).wasOk()&&decoded.rhythm.pitch==36&&decoded.rhythm.start==0&&decoded.rhythm.end==8,"Euclidean preset encoding excludes channel-specific pitch and range");
}
